import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"Nearby","description":"An overview of places near SCUT Wushan Campus","frontmatter":{"lang":"en-US","title":"Nearby","description":"An overview of places near SCUT Wushan Campus","llm_translated":true},"headers":[],"relativePath":"en/infra/wushan/nearby.md","filePath":"en/infra/wushan/nearby.md","lastUpdated":1791510705000}`),a={name:`en/infra/wushan/nearby.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/infra/wushan/nearby.md for this page in Markdown format</div><h1 id="around-wushan-campus" tabindex="-1">Around Wushan Campus <a class="header-anchor" href="#around-wushan-campus" aria-label="Permalink to “Around Wushan Campus”">​</a></h1><p>Wushan Campus sits in the heart of Guangzhou, with the bustling Tianhe District right outside the campus gates and a rich choice of dining, shopping, and entertainment nearby.</p><h2 id="dining" tabindex="-1">Dining <a class="header-anchor" href="#dining" aria-label="Permalink to “Dining”">​</a></h2><ul><li><strong>Around Wushan Station</strong>: exit through the East Gate or the East Side Gate to reach the area around Wushan Station, which is packed with all kinds of restaurants and snack shops</li><li><strong>Around Tianhe Coach Terminal</strong>: exit through the North Area North Gate next to Boxue Building, and a walk of a few hundred meters brings you to Tianhe Coach Terminal, with shopping areas such as Tianhe Xintiandi nearby and plenty of dining options</li></ul><p>TODO: Daily shopping &amp; supermarkets: nearby large supermarkets, wet markets, and fruit shops</p><h2 id="rentals" tabindex="-1">Rentals <a class="header-anchor" href="#rentals" aria-label="Permalink to “Rentals”">​</a></h2><p><strong>Xixiu Village</strong> inside Wushan Campus has staff housing available for rent, though prices are relatively high. Students with relevant experience are welcome to add more rental advice for the surrounding area.</p><h2 id="transit-connections" tabindex="-1">Transit Connections <a class="header-anchor" href="#transit-connections" aria-label="Permalink to “Transit Connections”">​</a></h2><h3 id="metro" tabindex="-1">Metro <a class="header-anchor" href="#metro" aria-label="Permalink to “Metro”">​</a></h3><ul><li><strong>Wushan Station (Line 3)</strong>: the most convenient metro station for the West, South, and East areas, reached by exiting through the East Gate or the East Side Gate</li><li><strong>Tianhe Coach Terminal (Line 3/Line 6)</strong>: the most convenient metro station for the North Area; exit through the North Area North Gate and walk a few hundred meters</li></ul><h3 id="cross-campus-transit" tabindex="-1">Cross-Campus Transit <a class="header-anchor" href="#cross-campus-transit" aria-label="Permalink to “Cross-Campus Transit”">​</a></h3><p>The most convenient and inexpensive way to get to University Town Campus and Guangzhou International Campus is the <strong>campus shuttle bus</strong>. Buses depart from stops such as the on-campus Library and reach University Town Campus and the International Campus via expressways.</p><ul><li><strong>Travel time</strong>: about 45~60 minutes from Wushan to the University Town Concert Hall; the International Campus falls within the same range, and morning and evening rush hours may make trips longer</li><li><strong>Frequency</strong>: more departures on weekdays than on weekends</li></ul><h2 id="leisure-entertainment" tabindex="-1">Leisure &amp; Entertainment <a class="header-anchor" href="#leisure-entertainment" aria-label="Permalink to “Leisure &amp; Entertainment”">​</a></h2><ul><li><strong>Tianhe Xintiandi</strong>: near Tianhe Coach Terminal, with a shopping mall, a cinema, and other facilities.</li><li>Students who know of entertainment spots around Wushan Station are welcome to add them.</li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};